{
  "type": "Screenshots from a cinematic open-world crime game, GTA-style trailer frames.",
  "aspect_ratio": "16:9 widescreen",
  "setting": {
    "location": "The dense, futuristic neon-lit streets of Chongqing/Hong Kong style in China at night",
    "weather": "The wet road surface after the heavy rain reflects light, damp with mist and moisture.",
    "background": "Towering skyscrapers, elevated highways that stretch across the skyline, crowded alleyway restaurants, electric vehicles, pedestrians, distant police lights, and a multitude of vertical Chinese neon signs and red lanterns.",
    "mood": "Resolute, expensive, dangerous, cyberpunk noir style, photorealistic game trailer stills"
  },
  "main_subjects": {
    "count": 2,
    "items": [
      {
        "description": "A black luxury sports car, photographed from a low rear 45-degree angle, is parked on a wet street. Its wide body, illuminated red taillights, and dark reflective paint covered in raindrops reveal a license plate with Chinese characters and the numbers A·7M650.",
        "position": "Left foreground"
      },
      {
        "description": "A stylish young woman leans against a car, her face deliberately blurred/covered, striking a confident pose, holding a smartphone in one hand.",
        "position": "Central Prospect",
        "outfit": {
          "count": 5,
          "pieces": [
            "black leather jacket",
            "Black fitted mini skirt",
            "Black sheer stockings",
            "Black ankle boots",
            "Small crossbody bag"
          ]
        }
      }
    ]
  },
  "game_hud": {
    "style": "The UI of this narrative-driven modern action game features a clear, semi-transparent dark panel with white text, yellow markers, and red and blue health bars.",
    "components_count": 5,
    "components": [
      {
        "name": "Minimap",
        "position": "Top left corner",
        "details": "A square street map with roads, player arrows, and icons; time: 22:47; weather: 24°C."
      },
      {
        "name": "Mission Objectives",
        "position": "Below the minimap",
        "text": "Meeting with Brother Jin / Heading to a private club near Hongyadong, Jiefangbei",
        "distance": "912 meters"
      },
      {
        "name": "Cash and mobile phone indicators",
        "position": "Top right corner",
        "text": "¥489,000, with smartphone icon"
      },
      {
        "name": "Player Status Panel",
        "position": "bottom left corner",
        "details": "Small female portrait, red health 100/100, blue armor or stamina 75/100, two skill icons."
      },
      {
        "name": "Weapon and ammunition panel",
        "position": "bottom right corner",
        "details": "Pistol icon, ammo 12/36"
      }
    ]
  },
  "visible_signage": {
    "count": 10,
    "labels": [
      "Yudu Mahjong Hall",
      "5F",
      "Four Seasons Like You Teahouse",
      "Hand-whipped lemon tea",
      "Jin Mantang",
      "Foot bath",
      "Old Place BBQ",
      "Meituan Waimai",
      "13",
      "Open 24 hours"
    ]
  },
  "composition": "A low-angle cinematic shot at street level, with a sports car occupying the left half, a woman positioned in the center next to the rear wheel, and bustling restaurant facades and electric vehicles on the right. The perspective of a deep urban canyon leads to a luminous tower.",
  "lighting": "High-contrast neon lights, red lantern halos, cyan and magenta reflections on wet asphalt, contour lighting around women and cars, realistic halo effects.",
  "quality": "Ultra-realistic, photo-quality 3D game rendering; Unreal Engine-like texture; ray-traced reflections; cinematic color grading; sharp foreground; atmospheric depth of field; no cartoonish style.",
  "customization": {
    "city": "{argument name=\"city\" default=\"Chongqing-style neon metropolis\"}",
    "vehicle": "{argument name=\"vehicle\" default=\"Black luxury sports car\"}",
    "character outfit": "{argument name=\"character outfit\" default=\"Black leather jacket and mini skirt\"}",
    "mission text": "{argument name=\"mission text\" default=\"Meeting with Brother Jin / Heading to a private club near Hongyadong, Jiefangbei\"}",
    "cash amount": "{argument name=\"cash amount\" default=\"¥ 489,000\"}"
  }
}

