{
  "type": "Minimalist isometric mobile app illustration",
  "subject": "The concept for a taxi booking service is outlined with simple black lines against a white background, accented with a few splashes of color.",
  "style": {
    "perspective": "3/4 isometric view",
    "linework": "Slender and precise gray-black outline, rounded corners, technical vector illustration.",
    "color_palette": "Primarily white and light gray, with {argument name=\"accent color\" default=\"Electric blue and violet\"} Decorations, and small coral-colored map markers.",
    "shading": "Extremely soft light gray shadows, subtle platform projections, and agglomerate gradations.",
    "background": "White background with faint isometric grid lines near the bottom."
  },
  "layout": {
    "count_discrete_elements": 7,
    "elements": [
      {
        "id": 1,
        "description": "The large, upright smartphone at the back features a rounded rectangular body with a thin profile, visible speaker grilles and side buttons, and a screen that is mostly blank."
      },
      {
        "id": 2,
        "description": "The floating circular map card in the upper left corner of the phone displays a light-colored street grid, a blue route with two turns, a blue starting point dot, and a coral-colored destination marker."
      },
      {
        "id": 3,
        "description": "The floating booking card below the map card displays text.{argument name=\"booking title\" default=\"Taxi booking\"} A small black taxi icon, with visible distance text.{argument name=\"distance text\" default=\"3-minute walk\"} And the purple circular arrow button on the right."
      },
      {
        "id": 4,
        "description": "The white taxi model located in the center of the platform is a compact sedan with black windows, blue side stripes, and prominently displayed headlights and grille. A white roof emblem bears the logo.{argument name=\"taxi sign text\" default=\"TAXI\"}"
