{
  "type": "Vertical photo-style English vocabulary notes page",
  "source_scene": "A realistic photograph of a convenience store or small supermarket aisle taken at eye level. Tall metal shelves are filled with snacks, drinks, milk, bread, tissues, and daily necessities; a red shopping basket containing fruit and groceries sits on the floor in the foreground; and an umbrella stand with a black umbrella is on the right.",
  "style": "Maintain the realism of the base image, then add cute white hand-drawn study note annotations above the photo, like casual marker writing; use rounded handwritten English fonts, white doodle outlines, arrows, glitter symbols, and soft shadows to ensure readability.",
  "aspect_ratio": "9:16 Vertical smartphone image",
  "layout": {
    "annotated_vocabulary_count": 5,
    "vocabulary_items": [
      {
        "word": "{argument name=\"first vocabulary word\" default=\"milk\"}",
        "example_sentence": "{argument name=\"first example sentence\" default=\"Milk is on the shelf.\"}",
        "target": "Milk bottles on the shelf in the upper right corner",
        "annotation": "Add a white, rounded outline around the milk bottle group, with arrows pointing from the words to the bottles, and place it near the upper right side."
      },
      {
        "word": "bottle",
        "example_sentence": "The bottle has water.",
        "target": "A bottle of dark water on the middle shelf",
        "annotation": "Add a small white outline around the bottle, and place the curved arrow and label in the middle left corner."
      },
      {
        "word": "bread",
        "example_sentence": "This bread is soft.",
        "target": "Bread in plastic packaging on the middle shelf on the right",
        "annotation": "Add large white outlines around several bags of bread, with arrows and labels placed in the center on the right."
      },
      {
        "word": "umbrella",
        "example_sentence": "The umbrella is by the shelf.",
        "target": "The black umbrella in the gray metal umbrella stand in the bottom right corner",
        "annotation": "Add white outlines along the umbrella and rack, and place arrows and labels in the bottom right corner."
      },
      {
        "word": "basket",
        "example_sentence": "The basket is red.",
        "target": "Red shopping basket on the foreground floor",
        "annotation": "Add a white outline around the shopping basket, and place the dashed curved arrows and labels in the bottom left corner."
      }
    ]
  },
  "visual_details": {
    "doodles": "Add small white glitter doodles to the blank areas in the upper left and lower left corners; add short, emphasizing strokes to the upper right corner and near the umbrella.",
    "text_treatment": "The vocabulary words are presented in uppercase and lowercase, with smaller example sentences below each word. All text is in white handwriting with subtle shading.",
    "composition": "Against the backdrop of busy supermarket shelves, labels remain clear and legible, placed near the corresponding items without obscuring too much merchandise.",
    "lighting": "Bright indoor fluorescent lighting creates a natural, candid feel.",
    "language_learning_goal": "Transform everyday photos into fun visual English vocabulary learning diary pages"
  }
}

